//#region node_modules/dictionary-api-client/dist/get-definition-for/index.js
async function getDefinitionFor({ word, lang = "en" }) {
	if (typeof fetch !== "function") throw new Error("[Bad]: Global Fetch Not Available");
	else {
		const API_URL = `https://api.dictionaryapi.dev/api/v2/entries/${lang}/${encodeURIComponent(word.trim())}`;
		try {
			const response = await fetch(API_URL);
			const definition = await response.json();
			if (!response.ok) throw new Error("[Bad]: Dictionary API Error", { cause: definition });
			else return {
				code: "api-ok",
				message: "No error encountered",
				payload: definition
			};
		} catch (error) {
			console.log(error);
			return {
				code: "api-fail",
				message: "Not Found",
				payload: error.cause
			};
		}
	}
}
//#endregion
export { getDefinitionFor };
